import { Difficulty, LexiconEntry, PuzzleCategory } from '../types/puzzle';

type RawTuple = [
  answer: string,
  category: Exclude<PuzzleCategory, 'all'>,
  difficulty: Difficulty,
  clueTr: string,
  clueFullTr: string,
  en: string,
  de: string,
  fr: string
];

function mapTuples(tuples: RawTuple[]): LexiconEntry[] {
  return tuples.map(([answer, category, difficulty, clueTr, clueFullTr, en, de, fr]) => ({
    answer,
    category,
    difficulty,
    clueTr,
    clueFullTr,
    gloss: { en, de, fr },
  }));
}

